package edu.uiu.aoop.careerforge.web;
import edu.uiu.aoop.careerforge.domain.Role; import edu.uiu.aoop.careerforge.event.CareerMilestoneEvent; import edu.uiu.aoop.careerforge.security.AppPrincipal; import java.util.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController public class LearningController { private final JdbcTemplate jdbc; private final ApplicationEventPublisher events; public LearningController(JdbcTemplate jdbc,ApplicationEventPublisher events){this.jdbc=jdbc;this.events=events;}
 @GetMapping("/resources") List<Map<String,Object>> resources(){return jdbc.queryForList("SELECT * FROM learning_resources WHERE status='published' ORDER BY featured DESC,created_at DESC");}
 @GetMapping("/assessments") List<Map<String,Object>> assessments(@AuthenticationPrincipal AppPrincipal p){return jdbc.queryForList("SELECT a.id,a.title,a.description,a.category,a.difficulty,a.time_limit_minutes,a.passing_percentage,COUNT(q.id) question_count,(SELECT MAX(aa.percentage) FROM assessment_attempts aa WHERE aa.assessment_id=a.id AND aa.user_id=?) best_score FROM assessments a LEFT JOIN questions q ON q.assessment_id=a.id AND q.status='published' WHERE a.status='published' GROUP BY a.id HAVING COUNT(q.id)>0 ORDER BY a.created_at DESC",p.id());}
 @GetMapping("/assessments/{id}/questions") List<Map<String,Object>> questions(@PathVariable Long id){List<Map<String,Object>> rows=jdbc.queryForList("SELECT id,prompt,question_type,difficulty,points FROM questions WHERE assessment_id=? AND status='published' ORDER BY id",id);for(Map<String,Object> row:rows)row.put("options",jdbc.queryForList("SELECT id,option_text FROM question_options WHERE question_id=? ORDER BY sort_order",row.get("id")));return rows;}
 @PostMapping("/assessments/{id}/submit") @Transactional Map<String,Object> submit(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id,@RequestBody Map<String,Object> body){List<Map<String,Object>> qs=jdbc.queryForList("SELECT id,points FROM questions WHERE assessment_id=? AND status='published'",id);if(qs.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"This assessment has no published questions");Map<Long,Long> answers=new HashMap<>();Object raw=body.get("answers");if(raw instanceof List<?> list)for(Object each:list)if(each instanceof Map<?,?> m)try{answers.put(Long.valueOf(String.valueOf(m.get("questionId"))),Long.valueOf(String.valueOf(m.get("optionId"))));}catch(NumberFormatException ignored){} double total=0,score=0;int correct=0;for(Map<String,Object> q:qs){Long qid=((Number)q.get("id")).longValue();double points=((Number)q.get("points")).doubleValue();total+=points;Long option=answers.get(qid);if(option!=null){Integer yes=jdbc.query("SELECT is_correct FROM question_options WHERE question_id=? AND id=?",rs->rs.next()?rs.getInt(1):0,qid,option);if(yes!=null&&yes==1){score+=points;correct++;}}}int percent=total==0?0:(int)Math.round(score*100/total);jdbc.update("INSERT INTO assessment_attempts (user_id,assessment_id,score,total_points,percentage,started_at,completed_at) VALUES (?,?,?,?,?,NOW(),NOW())",p.id(),id,score,total,percent);events.publishEvent(new CareerMilestoneEvent(p.id(),CareerMilestoneEvent.Type.ASSESSMENT_COMPLETED));return Map.of("score",score,"total",total,"percentage",percent,"correctAnswers",correct,"questionCount",qs.size());}
 @GetMapping("/events") List<Map<String,Object>> events(@AuthenticationPrincipal AppPrincipal p){if(p.role()!=Role.student)throw new ApiException(HttpStatus.FORBIDDEN,"Student account required");return jdbc.queryForList("SELECT e.*,EXISTS(SELECT 1 FROM event_registrations er WHERE er.event_id=e.id AND er.user_id=?) registered,(SELECT COUNT(*) FROM event_registrations er WHERE er.event_id=e.id) registration_count,IF(e.capacity IS NULL,NULL,GREATEST(0,e.capacity-(SELECT COUNT(*) FROM event_registrations er WHERE er.event_id=e.id))) seats_remaining FROM events e WHERE e.status='published' AND e.starts_at>=NOW() ORDER BY e.starts_at",p.id());}
 @PostMapping("/events/{id}/register") @Transactional Map<String,Object> register(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){if(p.role()!=Role.student)throw new ApiException(HttpStatus.FORBIDDEN,"Only students can reserve event seats");Map<String,Object> e=jdbc.query("SELECT id,capacity FROM events WHERE id=? AND status='published' AND starts_at>=NOW() FOR UPDATE",rs->{if(!rs.next())return null;Map<String,Object> event=new LinkedHashMap<>();event.put("id",rs.getLong("id"));event.put("capacity",rs.getObject("capacity"));return event;},id);if(e==null)throw new ApiException(HttpStatus.NOT_FOUND,"This event is no longer available");int current=jdbc.queryForObject("SELECT COUNT(*) FROM event_registrations WHERE event_id=?",Integer.class,id);Integer capacity=(Integer)e.get("capacity");int mine=jdbc.queryForObject("SELECT COUNT(*) FROM event_registrations WHERE event_id=? AND user_id=?",Integer.class,id,p.id());if(mine==0&&capacity!=null&&current>=capacity)throw new ApiException(HttpStatus.CONFLICT,"This event is fully reserved");if(mine==0)jdbc.update("INSERT INTO event_registrations (event_id,user_id) VALUES (?,?)",id,p.id());int count=current+(mine==0?1:0);Map<String,Object> r=new LinkedHashMap<>();r.put("message",mine==0?"Seat reserved successfully":"Your seat is already reserved");r.put("registered",true);r.put("registrationCount",count);r.put("seatsRemaining",capacity==null?null:Math.max(0,capacity-count));return r;}
 @DeleteMapping("/events/{id}/register") @Transactional Map<String,Object> cancel(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){int deleted=jdbc.update("DELETE FROM event_registrations WHERE event_id=? AND user_id=?",id,p.id());if(deleted==0)throw new ApiException(HttpStatus.NOT_FOUND,"You do not have an active reservation for this event");return Map.of("message","Reservation cancelled. Your seat is available again.","registered",false);}
}
